"""Spectral dichotomy of the geometric character sum S_N(omega)."""
from __future__ import annotations
import cmath, math

def e(x: float) -> complex:
    return cmath.exp(2.0 * math.pi * 1j * x)

def character_sum(omega: float, N: int) -> complex:
    base, total, power = e(omega), 0j, 1 + 0j
    for _ in range(N):
        total += power
        power *= base
    return total

def spectral_gap_bound(omega: float) -> float:
    s = abs(math.sin(math.pi * omega))
    return math.inf if s == 0.0 else 1.0 / s

if __name__ == "__main__":
    print("Resonance at integers (|S_N| = N):")
    for m in (0, 1, 2):
        for N in (10, 100, 1000):
            print(f"  omega={m}, N={N}: |S_N|={abs(character_sum(float(m), N)):.3f}")
    print("Spectral gap at non-integers (|S_N| <= 1/|sin(pi w)|, N-independent):")
    for omega in (1/3, math.sqrt(2) - 1, 0.1):
        b = spectral_gap_bound(omega)
        print(f"  omega={omega:.5f}, bound={b:.4f}")
        for N in (10, 100, 10000):
            print(f"    N={N}: |S_N|={abs(character_sum(omega, N)):.4f}")

"""The Nyquist bridge: (e(1/2))^n = (-1)^n selects the Collatz branch."""
from __future__ import annotations
import cmath, math

def e(x: float) -> complex:
    return cmath.exp(2.0 * math.pi * 1j * x)

def collatz(n: int) -> int:
    return n // 2 if n % 2 == 0 else 3 * n + 1

def collatz_fourier(n: int) -> int:
    even_branch = abs(e(0.5) ** n - 1.0) < 1e-9   # (e(1/2))^n == 1  <=>  n even
    return n // 2 if even_branch else 3 * n + 1

if __name__ == "__main__":
    print(f"e(1/2) = {e(0.5):.4f}")
    agree = all(collatz(n) == collatz_fourier(n) for n in range(1000))
    print(f"parity form and Fourier form agree on 1..999: {agree}")
    for n in (6, 7, 8, 27):
        print(f"  n={n}: T={collatz(n)}, Fourier T={collatz_fourier(n)}")

"""Exact stopping time of powers of two: T^[k](2^k) = 1."""
from __future__ import annotations
from typing import Callable

def collatz(n: int) -> int:
    return n // 2 if n % 2 == 0 else 3 * n + 1

def iterate(f: Callable[[int], int], n: int, k: int) -> int:
    for _ in range(k):
        n = f(n)
    return n

def stopping_time(n: int) -> int:
    steps = 0
    while n != 1:
        n = collatz(n)
        steps += 1
    return steps

if __name__ == "__main__":
    for k in range(0, 15):
        assert iterate(collatz, 2 ** k, k) == 1
        print(f"k={k:2d}: 2^k={2**k:6d}, T^[k](2^k)=1, stopping time={stopping_time(2**k)} (=k)")

