function spectral_gap_certificate(omega, N):
    base <- exp(2*pi*i*omega)
    total <- 0 ; power <- 1
    for n in 0 .. N-1:
        total <- total + power
        power <- power * base
    value <- |total|
    s <- |sin(pi*omega)|
    bound <- (s == 0) ? +infinity : 1/s
    return (value, bound, value <= bound)

function collatz_fourier_transform_split(omega, N):
    even_branch <- 0 ; odd_branch <- 0
    for n in 0 .. N-1:
        if n mod 2 == 0:
            even_branch <- even_branch + e(omega * (n / 2))
        else:
            odd_branch <- odd_branch + e(omega * (3n + 1))
    return even_branch + odd_branch

