from __future__ import annotations
import cmath, math

def e(x: float) -> complex:
    return cmath.exp(2.0 * math.pi * 1j * x)

def collatz(n: int) -> int:
    return n // 2 if n % 2 == 0 else 3 * n + 1

def collatz_fourier_transform(omega: float, N: int) -> complex:
    """Direct form F_N(omega) = sum_{n<N} e(omega * T(n))."""
    return sum((e(omega * collatz(n)) for n in range(N)), 0j)

def collatz_fourier_transform_split(omega: float, N: int) -> complex:
    """Parity split: halving (even) branch + tripling (odd) branch."""
    even_branch: complex = sum((e(omega * (n // 2)) for n in range(N) if n % 2 == 0), 0j)
    odd_branch: complex = sum((e(omega * (3 * n + 1)) for n in range(N) if n % 2 != 0), 0j)
    return even_branch + odd_branch

